def wrapper_identity(path):
    controls.equivalent_wrappers(path);image=controls.BASES[0];p=controls.oracle.image_pages(path,image);raw=_read_span(p,image+0x288610,12)
    assert raw==bytes.fromhex('012040a9e00308aa20001fd6')
    return dict(wrapper_offset='0x288610',target_offset='0x32a264',byte_count=12,sha256=hashlib.sha256(raw).hexdigest(),
        identical_to_existing_token_free_wrapper=True,no_PC_relative_instructions=True)

def zero_counter_control(path,image,alias):
    p,packed,pointer=controls.fresh(path,image,'pointer')
    if alias:pointer=packed+16;_write_span(p,packed+8,pointer.to_bytes(8,'little'))
    _write_span(p,pointer,bytes(4));expected_book={pointer:4};actual_book={pointer:4};expected=[];actual=[]
    def native_free(cpu):
        value=cpu.reg_read(controls.arm.UC_ARM64_REG_X0);assert value==pointer and expected_book.pop(value)==4
        expected.append(['free',value]);cpu.mem_write(value,b'\xD3'*4);return 0xDEADBEEF
    watch={(page<<12,4096):None for page in p};seen=set()
    def observe(cpu,pc):
        if pc-image in (0x288610,0x32A264,0x347FA0):seen.add(pc-image)
    _,_,allocations,services=controls.oracle.native(path,image,0x288610,[packed],p,host_imports={0x347FA0:native_free},observed_memory=watch,instruction_observer=observe)
    def free(tx,value):
        assert value==pointer and actual_book.pop(value)==4
        actual.append(['free',value]);_write_span(tx,value,b'\xD3'*4);return 0x1234
    result=controls.model(p,image,packed,free)
    assert result is None and seen=={0x288610,0x32A264,0x347FA0} and allocations==[] and services==[]
    assert expected==actual==[['free',pointer]] and expected_book==actual_book=={}
    assert all(_read_span(p,a,n)==raw for (a,n),raw in watch.items())
    print('PASS independent zero counter free',hex(image),'packed alias' if alias else 'separate storage',flush=True)
    return dict(image_base=hex(image),case='independent_zero_counter_packed_alias' if alias else 'independent_zero_counter',defined_counter_width=4,initial_count_zero=True,
        original_new_wrapper_and_operator_delete_returned=True,all_pages_and_explicit_provider_effects_equal=True,owning_bookkeeping_removed=True,
        model_void_result_is_None=True,no_packed_result_store=True,component_free_provider_explicit=True,native_snapshot_input=False,native_physical_X0_compared=False)

